    },
    {
      "вещество": "Маннитол",
      "содержание": "≈ 1–5 % от сухого веса (типичный диапазон для Amanita)",
      "влияние": "Лёгкое осмотическое действие, в пищевых количествах нетоксичен."
    }
  ]
}

